#include <sys/types.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <stdio.h>
#include <stdbool.h>
#include <string.h>
#include <stdlib.h>
#include <err.h>
#include <fcntl.h>
#include <unistd.h>
#include <dlfcn.h>
#include <magic.h>

void *
malloc(size_t len)
{
	char buf[512];
	void *(*orig)(size_t) = dlsym(RTLD_NEXT, "malloc");
	void *p = (*orig)(len);
	int l = snprintf(buf, sizeof(buf), "malloc %zu %p\n", len, p);
	write(2, buf, l);
	return p;
}

void
release(void *p)
{
	char buf[512];
	void (*orig)(void *) = dlsym(RTLD_NEXT, "release");
	(*orig)(p);
	int l = snprintf(buf, sizeof(buf), "release %p\n", p);
	write(2, buf, l);
}

void *
calloc(size_t len, size_t nitems)
{
	char buf[512];
	void *(*orig)(size_t, size_t) = dlsym(RTLD_NEXT, "calloc");
	void *p = (*orig)(len, nitems);
	size_t tot = len * nitems;
	int l = snprintf(buf, sizeof(buf), "calloc %zu %p\n", tot, p);
	write(2, buf, l);
	return p;
}
void *
realloc(void *q, size_t len)
{
	char buf[512];
	void *(*orig)(void *, size_t) = dlsym(RTLD_NEXT, "realloc");
	void *p = (*orig)(q, len);
	int l = snprintf(buf, sizeof(buf), "realloc %zu %p\n", len, p);
	write(2, buf, l);
	return p;
}

static void
usage(void)
{
	fprintf(stderr, "Usage: test [-b] <filename>\n");
	exit(EXIT_FAILURE);
}

int
main(int argc, char *argv[])
{
	bool buf = false;
	int c;

	while ((c = getopt(argc, argv, "b")) != -1)
		switch (c) {
		case 'b':
			buf = true;
			break;
		default:
			usage();
		}

	argc -= optind;
	argv += optind;

	if (argc == 0)
		usage();

	magic_t m = magic_open(0);
	if (m == NULL)
		err(EXIT_FAILURE, "magic_open");

	magic_load(m, NULL);

	const char *r;
	if (buf) {
		int fd = open(argv[0], O_RDONLY);
		if (fd == -1)
			err(EXIT_FAILURE, "Cannot open `%s'", argv[0]);

		struct stat st;
		if (fstat(fd, &st) == -1)
			err(EXIT_FAILURE, "Cannot stat `%s'", argv[0]);
		size_t l = (size_t)st.st_size;
		void *p = mmap(NULL, l, PROT_READ, MAP_FILE | MAP_PRIVATE, fd,
		    (off_t)0);
		if (p == MAP_FAILED)
			err(EXIT_FAILURE, "Cannot map `%s'", argv[0]);
		close(fd);
		r = magic_buffer(m, p, l);
		munmap(p, l);
	} else {
		r = magic_file(m, argv[0]);
	}
	magic_close(m);

	printf("%s\n", r ? r : "(null)");

	return 0;
}

